Lemma gc_post_rdn : forall gb (mem0 Mf : word -> option byte) lo hi fs col a (n : nat), gc_postb gb mem0 Mf lo hi fs col ->
  (0 <= a)%Z -> (a + Z.of_nat n <= 2 ^ 64)%Z ->
  (a + Z.of_nat n <= lo \/ hi <= a)%Z -> (a + Z.of_nat n <= fs + 96 \/ fs + 97 <= a)%Z ->
