  Variables c sh g35 : Z.                      (* [comment removed for export] *)
  Hypothesis Hc : (0 <= c <= 6)%Z.
  Hypothesis Hsh : (0 <= sh)%Z /\ (sh + 8 * 2 ^ c < 2 ^ 64)%Z.
  Hypothesis Hok : store_ok ASEGS M (Z_to_bv 64 sh) (Z.to_nat (8 * 2 ^ c)) = true.

