  Lemma pow_c_bounds : (1 <= 2 ^ c <= 64)%Z.
  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SO0|10;!1,70!2'61/c;!1,7|600;!2'^>13!2'4,<1!2'613%~R5%~R!2'2,<3!2'4,<6!2'2,<1$Ha;R8$~R+^8!3'^?13#2%Ha;R8%~R+^8!2'2,<6!2'^>1/c;!2'2,</c;%~R5%~R<!2'4,<2$Ha;R8$~R+^8!3'^?1/c;#2%Ha;R8%~R+^8!2'2,<2!1,=+>!1+?+>!1+A+0!1+C+0!2,J+0,<!2'RC,F!4'S#1#3vv!2,T+U,V!3+;+U!2'W#1#3,V!3'X+0,<#2&__sat39;R47&__sat38;R9:&__sat37;R;=&__sat36;R>?&__arith;R&__wit;R@A&__varmap;R!1,^I+0B&__ff;R!7,HC'D+E+E,F!4,I+0D,^J!2,J+01,NEF5#1!2,@+0#2!2,L+0,M!7,HC'D+E+E,F!4,I+0D,KI,N!6,^KC'D+E+E,F#4!1,O+E!1,7|22;!7,HC'D+E+E,F!4,I+0I,K!2,J+0M,N!4,^6!2'2!1,7,M2!2'223!5'^Q1,</c;G&__sat39;R47&__sat38;R9:&__sat37;R;=&__sat36;R>?&__arith;R$__p1;Rw$__x1;R+0&__wit;R@A&__varmap;RHB&__ff;R!8,BC'D+E+E,F!7,GC'D+E+E,FJKLJEF%__p1;Rw%__x1;R+0%~R!2+1!2'2,<#1#2!2'2,<#2!3#1!2'2/c;M/c;/Hc;!5'^Q1/c;MG&__sat39;R47&__sat38;R9:&__sat37;R;=&__sat36;R>?&__arith;R$__p1;Rw$__x1;R+0&__wit;R@A&__varmap;RHB&__ff;R!8,BC'D+E+E,F!7,GC'D+E+E,FKNLNEF%__p1;Rw%__x1;R+0%~R!2+1#2!2'2#1M!2'2#2M!3#1</c;/Hc;").
