  Lemma gs_keeps_trans : forall r1 r2 r3, gs_keeps r1 r2 -> gs_keeps r2 r3 -> gs_keeps r1 r3.
  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S70|21;!1,_?0!1+_M!1,_?|600;!2'a012!2'bN#3#2!1+_M1|40;$r1;R3$r2;R3$r3;R3$K1;R4$K2;R4vd$r;R5$~R!1'`=!3+;5#1!3,a21!1,70,^9$~R!1'`=!3+;5#2!3,a21!1,7|32;,^9$~R!1'`=!3+;5#3!3,a21!1,7|33;,^9$~R!1'`=!3+;5#4!3,a21!1,7|34;,^9$~R!1'`=!3+;5#5!3,a21!1,7|35;,^9$~R!1'`=!3+;5#6!3,a21!1,7|36;,^9$~R!1'`=!3+;5#7!3,a21!1,7|37;,^9$~R!1'`=!3+;5#8!3,a21!1,76,^9$~R!1'`=!3+;5#9!3,a21!1,7|41;,^9!6'\2!2'a1#>#:$b;R2!3+;2#1!2'a1#@#;!:#<#:#9#8#7#6#5#4#3#2#1!2'a1#=#:!:#;#:#9#8#7#6#5#4#3#2#1!2'bN#5#3").
Qed.

  #[local] Ltac kp9 := intros r; intros; repeat (rewrite getr_other; [| intros ->; match goal with Hn : ?a <> ?a |- _ => exact (Hn eq_refl) end]); reflexivity.

  Lemma gcc_slot_run : forall regs M i,
    gi2_inv regs i -> (0 <= i < nfr)%Z -> GCM (gc_done_lt c i) M -> frm M ->
    exists regs' M',
